import torch
import avelang
import avelang.language as al

@avelang.jit
def test_loop_count(
    out_ptr: al.Pointer(al.i32),
    num: al.i32,
):
    tid = al.thread_id(0)
    if tid == 0:
        layout = al.make_layout((num,), (1,))
        out = al.make_tensor(out_ptr, al.i32, layout)
        count = al.convert(0, al.i32)
        for i in al.range(0, 32768):
            if i < num:
                out[i] = i
                count = count + al.convert(1, al.i32)
        # Store count at the very end
        if num > al.convert(0, al.i32):
            out[num - al.convert(1, al.i32)] = count

if __name__ == "__main__":
    for N in [256, 512, 1024]:
        out = torch.zeros(N, dtype=torch.int32, device='cuda')
        test_loop_count[lambda: ((1,1,1),(1,1,1))](out, N)
        print(f'N={N}: last={out[-1].item()}')
        # Check first few values
        print(f'  first 4: {out[:4].tolist()}')
        print(f'  last 4: {out[-4:].tolist()}')
