import torch
import avelang
import avelang.language as al

@avelang.jit
def test_convert_chain(
    x_ptr: al.Pointer(al.bf16),
    out_ptr: al.Pointer(al.bf16),
    num: al.i32,
):
    layout = al.make_layout((num,), (1,))
    x = al.make_tensor(x_ptr, al.bf16, layout)
    out = al.make_tensor(out_ptr, al.bf16, layout)
    tid = al.thread_id(0)
    if tid == 0:
        # Just store x values directly to out, no accumulation
        for i in al.range(0, 32768):
            if i < num:
                out[i] = x[i]

if __name__ == "__main__":
    torch.manual_seed(42)
    for N in [512, 1024, 4096]:
        x = torch.rand(N, dtype=torch.bfloat16, device='cuda')
        out = torch.empty(N, dtype=torch.bfloat16, device='cuda')
        test_convert_chain[lambda: ((1,1,1),(1,1,1))](x, out, N)
        match = torch.equal(x, out)
        print(f'N={N}: direct copy match={match}')
